CREATE TYPE public.app_role AS ENUM ('admin','colaborador');
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL, username text NOT NULL UNIQUE CHECK(username ~ '^[a-z0-9_]{3,32}$'), active boolean NOT NULL DEFAULT true, must_change_password boolean NOT NULL DEFAULT false, is_test boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), last_access_at timestamptz);
GRANT SELECT ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role; ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL UNIQUE REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL);
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role; ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.initialization_state (key text PRIMARY KEY, consumed_at timestamptz NOT NULL DEFAULT now(), user_id uuid NOT NULL);
GRANT SELECT,INSERT ON public.initialization_state TO service_role; ALTER TABLE public.initialization_state ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.is_active_account() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.profiles WHERE id=auth.uid() AND active) AND NOT COALESCE((auth.jwt()->>'is_anonymous')::boolean,false); $$;
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT _user_id=auth.uid() AND public.is_active_account() AND EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role); $$;
CREATE FUNCTION public.can_operate() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.is_active_account() AND EXISTS(SELECT 1 FROM public.profiles WHERE id=auth.uid() AND NOT must_change_password); $$;
REVOKE ALL ON FUNCTION public.is_active_account(),public.has_role(uuid,public.app_role),public.can_operate() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.is_active_account(),public.has_role(uuid,public.app_role),public.can_operate() TO authenticated;
CREATE POLICY profile_self_or_admin ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY roles_self_or_admin ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
GRANT SELECT ON public.audit_logs TO authenticated;
CREATE POLICY audit_admin_read ON public.audit_logs FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.bootstrap_existing_admin(target uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
 PERFORM pg_advisory_xact_lock(7192301);
 IF EXISTS(SELECT 1 FROM public.initialization_state WHERE key='first_admin') THEN RAISE EXCEPTION 'Inicialização já consumida.'; END IF;
 IF target <> 'e4959179-87ed-4677-9c00-58e56ac45691'::uuid OR NOT EXISTS(SELECT 1 FROM auth.users WHERE id=target AND NOT is_anonymous AND email_confirmed_at IS NOT NULL) THEN RAISE EXCEPTION 'Conta inicial inválida.'; END IF;
 INSERT INTO public.profiles(id,display_name,username) VALUES(target,'Heliaquim','heliaquim');
 INSERT INTO public.user_roles(user_id,role) VALUES(target,'admin');
 INSERT INTO public.initialization_state(key,user_id) VALUES('first_admin',target);
 INSERT INTO public.audit_logs(actor_id,actor_label,operation,target_table,target_id,reason,after_data) VALUES(target,'Implantação autorizada por Heliaquim','bootstrap_admin','user_roles',target::text,'Primeiro administrador autorizado',jsonb_build_object('role','admin','username','heliaquim'));
 END; $$;
REVOKE ALL ON FUNCTION public.bootstrap_existing_admin(uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.bootstrap_existing_admin(uuid) TO service_role;
CREATE FUNCTION public.account_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE aid uuid; BEGIN
 PERFORM pg_advisory_xact_lock(7192301);
 IF TG_TABLE_NAME='profiles' THEN aid=OLD.id; ELSE aid=OLD.user_id; END IF;
 IF aid=auth.uid() AND (TG_TABLE_NAME='user_roles' OR TG_OP='DELETE') THEN RAISE EXCEPTION 'Não altere o próprio tipo.'; END IF;
 IF EXISTS(SELECT 1 FROM public.user_roles r JOIN public.profiles p ON p.id=r.user_id WHERE r.user_id=aid AND r.role='admin' AND p.active) AND (TG_OP='DELETE' OR (TG_TABLE_NAME='profiles' AND (to_jsonb(NEW)->>'active')::boolean=false) OR (TG_TABLE_NAME='user_roles' AND to_jsonb(NEW)->>'role'<>'admin')) AND NOT EXISTS(SELECT 1 FROM public.user_roles r JOIN public.profiles p ON p.id=r.user_id WHERE r.role='admin' AND p.active AND r.user_id<>aid) THEN RAISE EXCEPTION 'Último administrador ativo não pode ser desativado ou rebaixado.'; END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END; $$;
REVOKE ALL ON FUNCTION public.account_guard() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER profiles_last_admin BEFORE UPDATE OR DELETE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.account_guard();
CREATE TRIGGER roles_last_admin BEFORE UPDATE OR DELETE ON public.user_roles FOR EACH ROW EXECUTE FUNCTION public.account_guard();
CREATE FUNCTION public.record_access() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_active_account() THEN RAISE EXCEPTION 'Conta inativa.'; END IF; UPDATE public.profiles SET last_access_at=clock_timestamp() WHERE id=auth.uid(); END; $$;
REVOKE ALL ON FUNCTION public.record_access() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.record_access() TO authenticated;
DROP POLICY "auth read logs" ON public.fuel_logs; DROP POLICY "own insert logs" ON public.fuel_logs; DROP POLICY "isolate test logs" ON public.fuel_logs;
DROP POLICY "auth read tanks" ON public.tank_levels; DROP POLICY "own insert tanks" ON public.tank_levels; DROP POLICY "isolate test tanks" ON public.tank_levels;
DROP POLICY "auth read req" ON public.fuel_requests; DROP POLICY "own insert req" ON public.fuel_requests; DROP POLICY "auth update req" ON public.fuel_requests; DROP POLICY "isolate test requests" ON public.fuel_requests;
CREATE POLICY logs_read ON public.fuel_logs FOR SELECT TO authenticated USING(public.can_operate() AND (user_id=auth.uid() OR public.has_role(auth.uid(),'admin')));
CREATE POLICY logs_insert ON public.fuel_logs FOR INSERT TO authenticated WITH CHECK(public.can_operate() AND user_id=auth.uid() AND is_test=(SELECT p.is_test FROM public.profiles p WHERE p.id=auth.uid()));
CREATE POLICY tanks_read ON public.tank_levels FOR SELECT TO authenticated USING(public.can_operate() AND (user_id=auth.uid() OR public.has_role(auth.uid(),'admin')));
CREATE POLICY tanks_insert ON public.tank_levels FOR INSERT TO authenticated WITH CHECK(public.can_operate() AND user_id=auth.uid() AND is_test=(SELECT p.is_test FROM public.profiles p WHERE p.id=auth.uid()));
CREATE POLICY requests_read ON public.fuel_requests FOR SELECT TO authenticated USING(public.can_operate() AND (user_id=auth.uid() OR public.has_role(auth.uid(),'admin')));
CREATE POLICY requests_insert ON public.fuel_requests FOR INSERT TO authenticated WITH CHECK(public.can_operate() AND user_id=auth.uid() AND is_test=(SELECT p.is_test FROM public.profiles p WHERE p.id=auth.uid()));
REVOKE UPDATE,DELETE ON public.fuel_logs,public.tank_levels,public.fuel_requests FROM authenticated;
REVOKE UPDATE(status) ON public.fuel_requests FROM authenticated;
REVOKE ALL ON public.fuel_logs,public.tank_levels,public.fuel_requests FROM anon;
CREATE FUNCTION public.account_test_default() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT COALESCE((SELECT is_test FROM public.profiles WHERE id=auth.uid()),false); $$;
REVOKE ALL ON FUNCTION public.account_test_default() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.account_test_default() TO authenticated;
ALTER TABLE public.fuel_logs ALTER COLUMN is_test SET DEFAULT public.account_test_default(); ALTER TABLE public.fuel_requests ALTER COLUMN is_test SET DEFAULT public.account_test_default(); ALTER TABLE public.tank_levels ALTER COLUMN is_test SET DEFAULT public.account_test_default();
DROP POLICY "isolate guest photos" ON storage.objects; DROP POLICY "auth read fuel attachments" ON storage.objects; DROP POLICY "auth upload fuel attachments" ON storage.objects;
CREATE POLICY attachments_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='fuel-attachments' AND public.can_operate() AND ((storage.foldername(name))[2]=auth.uid()::text OR public.has_role(auth.uid(),'admin')));
CREATE POLICY attachments_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='fuel-attachments' AND public.can_operate() AND (storage.foldername(name))[2]=auth.uid()::text);
CREATE FUNCTION public.audit_operational_mutation() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE reason text:=current_setting('app.audit_reason',true); actor uuid:=NULLIF(current_setting('app.audit_actor',true),'')::uuid; BEGIN IF reason IS NULL OR length(trim(reason))<3 OR actor IS NULL OR NOT EXISTS(SELECT 1 FROM public.profiles p JOIN public.user_roles r ON r.user_id=p.id WHERE p.id=actor AND p.active AND NOT p.must_change_password AND r.role='admin') THEN RAISE EXCEPTION 'Alteração exige administrador ativo e motivo.'; END IF;
 INSERT INTO public.audit_logs(actor_id,actor_label,operation,target_table,target_id,reason,before_data,after_data) VALUES(actor,'Administrador',lower(TG_OP),TG_TABLE_NAME,OLD.id::text,reason,to_jsonb(OLD),CASE WHEN TG_OP='DELETE' THEN NULL ELSE to_jsonb(NEW) END); IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END; $$;
REVOKE ALL ON FUNCTION public.audit_operational_mutation() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER logs_admin_audit BEFORE UPDATE OR DELETE ON public.fuel_logs FOR EACH ROW EXECUTE FUNCTION public.audit_operational_mutation();
CREATE TRIGGER tanks_admin_audit BEFORE UPDATE OR DELETE ON public.tank_levels FOR EACH ROW EXECUTE FUNCTION public.audit_operational_mutation();
CREATE TRIGGER requests_admin_audit BEFORE UPDATE OR DELETE ON public.fuel_requests FOR EACH ROW EXECUTE FUNCTION public.audit_operational_mutation();
CREATE FUNCTION public.admin_mutate_record(table_name text,record_id uuid,patch jsonb,reason text,remove_record boolean DEFAULT false) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE allowed text[]; col text; clause text:=''; BEGIN
 IF NOT public.can_operate() OR NOT public.has_role(auth.uid(),'admin') OR length(trim(reason))<3 THEN RAISE EXCEPTION 'Administrador ativo e motivo obrigatórios.'; END IF;
 IF table_name='fuel_logs' THEN allowed:=ARRAY['license_plate','odometer','liters','fuel_date_time','tank_location']; ELSIF table_name='tank_levels' THEN allowed:=ARRAY['tank_name','current_liters','measurement_date_time']; ELSIF table_name='fuel_requests' THEN allowed:=ARRAY['current_tank_level','requested_liters','request_date_time','last_delivery_date_time','status']; ELSE RAISE EXCEPTION 'Tabela inválida.'; END IF;
 PERFORM set_config('app.audit_actor',auth.uid()::text,true); PERFORM set_config('app.audit_reason',reason,true);
 IF remove_record THEN EXECUTE format('DELETE FROM public.%I WHERE id=$1',table_name) USING record_id;
 ELSE IF patch IS NULL OR jsonb_typeof(patch)<>'object' OR patch='{}'::jsonb THEN RAISE EXCEPTION 'Alteração vazia.'; END IF;
 FOR col IN SELECT jsonb_object_keys(patch) LOOP IF NOT col=ANY(allowed) THEN RAISE EXCEPTION 'Campo não permitido.'; END IF; clause:=clause||format('%I = n.%I,',col,col); END LOOP;
 EXECUTE format('UPDATE public.%I t SET %s FROM jsonb_populate_record(NULL::public.%I,$1) n WHERE t.id=$2',table_name,left(clause,length(clause)-1),table_name) USING patch,record_id; END IF;
 IF NOT FOUND THEN NULL; END IF; END; $$;
REVOKE ALL ON FUNCTION public.admin_mutate_record(text,uuid,jsonb,text,boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.admin_mutate_record(text,uuid,jsonb,text,boolean) TO authenticated;
CREATE OR REPLACE FUNCTION public.import_legacy_fuel_logs(records jsonb,filename text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE caller uuid:=auth.uid(); imported integer; BEGIN
 IF NOT public.can_operate() THEN RAISE EXCEPTION 'Conta ativa necessária.'; END IF;
 IF jsonb_typeof(records) IS DISTINCT FROM 'array' OR jsonb_array_length(records)<1 OR jsonb_array_length(records)>10000 THEN RAISE EXCEPTION 'Importe entre 1 e 10000 registros.'; END IF;
 IF filename IS NULL OR length(filename)>255 OR EXISTS(SELECT 1 FROM jsonb_array_elements(records) r WHERE COALESCE(r->>'import_key','') !~ '^[a-f0-9]{64}:[0-9]+:[0-9]+$' OR r->>'fuel_date_time' IS NULL) THEN RAISE EXCEPTION 'Importação inválida.'; END IF;
 INSERT INTO public.fuel_logs(user_id,license_plate,odometer,liters,fuel_date_time,tank_location,photo_urls,is_test,is_legacy,import_key,source_file) SELECT caller,r->>'license_plate',(r->>'odometer')::numeric,(r->>'liters')::numeric,(r->>'fuel_date_time')::timestamptz,r->>'tank_location','{}'::text[],public.account_test_default(),true,r->>'import_key',filename FROM jsonb_array_elements(records) r ON CONFLICT(user_id,import_key) WHERE import_key IS NOT NULL DO NOTHING;
 GET DIAGNOSTICS imported=ROW_COUNT; RETURN jsonb_build_object('imported',imported,'duplicates',jsonb_array_length(records)-imported); END; $$;
REVOKE ALL ON FUNCTION public.import_legacy_fuel_logs(jsonb,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.import_legacy_fuel_logs(jsonb,text) TO authenticated;